    "Các tài liệu được sử dụng làm cơ sở đối chiếu trong toàn bộ dự án.": "ドキュメントはプロジェクト全体を通じて比較の基礎として使用されます。",
    "Các tiêu chuẩn màu sắc và hoàn thiện bề mặt đã được duyệt.": "承認された色および表面仕上げ基準。",
