    "Xác nhận vật liệu được cắt đúng kích thước và đúng quy cách trước khi chuyển sang gia công.": "가공을 진행하기 전에 재료가 올바른 크기와 사양으로 절단되었는지 확인하십시오.",
    "Xuất hàng": "수출품",
