    "Báo cáo được thực hiện bởi hoạt động kiểm tra độc lập theo yêu cầu của dự án hoặc buyer.": "Le rapport est réalisé par une activité d'inspection indépendante à la demande du projet ou de l'acheteur.",
    "Báo cáo được thực hiện ở những giai đoạn nào?": "A quelles étapes le rapport est-il réalisé ?",
