    "Báo cáo QC độc lập": "Rapport de contrôle qualité indépendant",
    "Bao gồm: Hình sản phẩm, Hình lỗi nếu có, Hình đóng gói, Hình container, Hình kiểm tra thực tế.": "Comprend : image du produit, image d'erreur le cas échéant, image de l'emballage, image du conteneur, image d'inspection réelle.",
    "Bao gồm: Kích thước, Kết cấu, Hoàn thiện, Chức năng, Đóng gói, Số lượng.": "Y compris : taille, structure, finition, fonction, emballage, quantité.",
    "Bao gồm: Mô tả sai lệch, Mức độ ảnh hưởng, Đề xuất xử lý, Tình trạng khắc phục.": "Y compris : description de l'écart, niveau d'impact, traitement suggéré, état d'assainissement.",
    "Bao gồm: Tên dự án, Buyer, Nhà máy, Mã sản phẩm, Ngày kiểm tra, Người thực hiện.": "Y compris : nom du projet, acheteur, usine, code produit, date d'inspection, exécutant.",
    "Bảo vệ bề mặt": "Protection des surfaces",
    "Bảo vệ các khu vực dễ trầy xước hoặc hư hỏng trong quá trình vận chuyển.": "Protégez les zones facilement rayées ou endommagées pendant le transport.",
    "Bảo vệ cạnh và góc sản phẩm.": "Protégez les bords et les coins du produit.",
    "Bảo vệ kết cấu": "Protection structurelle",
    "Bảo vệ sản phẩm": "Protection du produit",
    "Bảo vệ sản phẩm trong quá trình lưu kho và vận chuyển.": "Protégez les produits pendant le stockage et le transport.",
    "Bề mặt": "Surface",
    "Bề mặt gia công": "Surface usinée",
    "Bề mặt hoàn thiện": "Finition superficielle",
    "Bề mặt sơn": "Surface peinte",
    "Bề mặt vật liệu": "Surface du matériau",
    "Biên bản xử lý sai lệch (nếu có)": "Procès-verbaux de traitement des écarts (le cas échéant)",
    "Biến dạng": "Déformation",
    "Bộ phận tủ": "Pièces d'armoire",
    "Bộ phụ kiện": "Ensemble d'accessoires",
    "Bộ vít": "Jeu de vis",
    "Buyer có thể gửi bản vẽ kỹ thuật, checklist QC hoặc tiêu chuẩn sản xuất để ANSLIFE đánh giá và đề xuất phương án kiểm tra phù hợp.": "Les acheteurs peuvent soumettre des dessins techniques, des listes de contrôle de contrôle qualité ou des normes de production à ANSLIFE pour évaluer et proposer des plans d'inspection appropriés.",
    "Buyer có thể gửi bản vẽ, tiêu chuẩn chất lượng, checklist QC hoặc yêu cầu kiểm tra để ANSLIFE đánh giá và đề xuất quy trình kiểm soát phù hợp.": "Les acheteurs peuvent soumettre des dessins, des normes de qualité, des listes de contrôle de contrôle qualité ou des demandes d'inspection à ANSLIFE pour évaluer et proposer des procédures de contrôle appropriées.",
    "Buyer có thể gửi checklist QC, tiêu chuẩn kiểm tra hoặc yêu cầu đánh giá riêng để ANSLIFE xây dựng phương án kiểm tra phù hợp trước khi giao hàng.": "L'acheteur peut envoyer une liste de contrôle de contrôle qualité, des normes d'inspection ou demander une évaluation distincte afin qu'ANSLIFE puisse développer un plan d'inspection approprié avant la livraison.",
    "Buyer có thể gửi danh mục vật liệu, bản vẽ, mẫu vật liệu hoặc tiêu chuẩn kỹ thuật để ANSLIFE đánh giá và đề xuất phương án kiểm tra phù hợp.": "L'acheteur peut soumettre une liste de matériaux, des dessins, des échantillons de matériaux ou des normes techniques à ANSLIFE pour évaluer et proposer des plans d'inspection appropriés.",
    "Buyer có thể gửi mẫu sản phẩm, mẫu vật liệu, bảng màu, bản vẽ kỹ thuật hoặc tiêu chuẩn đóng gói để ANSLIFE xây dựng phương án quản lý và kiểm soát phù hợp.": "Les acheteurs peuvent envoyer des échantillons de produits, des échantillons de matériaux, des palettes de couleurs, des dessins techniques ou des normes d'emballage à ANSLIFE pour développer un plan de gestion et de contrôle approprié.",
    "Buyer có thể gửi tiêu chuẩn đóng gói, quy cách carton, yêu cầu pallet hoặc hướng dẫn vận chuyển để ANSLIFE đánh giá và đề xuất phương án phù hợp.": "L'acheteur peut envoyer des normes d'emballage, des spécifications de carton, des exigences en matière de palettes ou des instructions d'expédition à ANSLIFE pour évaluer et proposer une solution appropriée.",
    "Buyer có thể gửi tiêu chuẩn kỹ thuật, mẫu sản phẩm, checklist QC hoặc yêu cầu kiểm tra để ANSLIFE đánh giá và đề xuất phương án kiểm soát phù hợp.": "Les acheteurs peuvent envoyer des normes techniques, des échantillons de produits, des listes de contrôle de contrôle qualité ou des demandes d'inspection à ANSLIFE pour évaluer et proposer des plans de contrôle appropriés.",
    "Buyer có thể gửi yêu cầu kỹ thuật, tiêu chuẩn chất lượng hoặc điều kiện sử dụng của sản phẩm để ANSLIFE đánh giá và đề xuất phương án kiểm soát phù hợp.": "Les acheteurs peuvent soumettre des exigences techniques, des normes de qualité ou des conditions d'utilisation des produits à ANSLIFE pour évaluer et proposer des plans de contrôle appropriés.",
    "Buyer có thể gửi yêu cầu về biểu mẫu báo cáo, checklist QC hoặc tiêu chuẩn đánh giá để ANSLIFE xây dựng hệ thống báo cáo phù hợp với từng dự án.": "Les acheteurs peuvent envoyer des demandes de formulaires de rapport, de listes de contrôle de contrôle qualité ou de normes d'évaluation afin qu'ANSLIFE puisse créer un système de reporting adapté à chaque projet.",
    "Buyer có thể theo dõi kết quả kiểm tra một cách rõ ràng.": "L'acheteur peut surveiller clairement les résultats de l'inspection.",
    "Các báo cáo kiểm tra được lưu cùng với mẫu duyệt, bản vẽ kỹ thuật, bảng màu, tiêu chuẩn đóng gói và checklist QC nhằm hỗ trợ truy xuất và duy trì tính nhất quán cho các dự án dài hạn.": "Les rapports d'inspection sont enregistrés avec des échantillons d'approbation, des dessins techniques, des nuanciers, des normes d'emballage et des listes de contrôle de contrôle qualité pour faciliter la traçabilité et maintenir la cohérence des projets à long terme.",
    "Các bộ phận điều chỉnh": "Pièces de réglage",
    "Các bộ phận và cấu kiện được xác nhận trước khi sản xuất hàng loạt.": "Les pièces et composants sont validés avant la production en série.",
    "Các công đoạn gia công và lắp ráp được kiểm tra định kỳ.": "Les étapes d’usinage et d’assemblage sont inspectées périodiquement.",
    "CÁC CÔNG ĐOẠN KIỂM TRA CHÍNH": "PRINCIPALES ÉTAPES DE CONTRÔLE",
    "Các công đoạn sản xuất được đối chiếu liên tục với mẫu chuẩn nhằm giảm thiểu sai lệch.": "Les étapes de production sont continuellement comparées aux échantillons standards afin de minimiser les écarts.",
    "Các hình thức đóng gói": "Formes d'emballage",
    "Các loại báo cáo ANSLIFE có thể cung cấp": "Types de rapports qu'ANSLIFE peut fournir",
    "CÁC NHÓM VẬT LIỆU ĐƯỢC KIỂM SOÁT": "GROUPES DE MATÉRIAUX CONTRÔLÉS",
