    "Kiểm tra cuối": "Vérification finale",
    "Kiểm tra cuối là bước đánh giá tổng thể sản phẩm sau khi hoàn thành sản xuất và hoàn thiện bề mặt. Hoạt động này giúp xác nhận sản phẩm phù hợp với yêu cầu của dự án trước khi đóng gói hoặc xuất khẩu.": "L'inspection finale est l'étape permettant d'évaluer le produit global une fois la production et la finition de surface terminées. Cette activité permet de confirmer la conformité du produit aux exigences du projet avant son emballage ou son exportation.",
