    "Sản phẩm được so sánh với mẫu đã được buyer phê duyệt nhằm đảm bảo tính đồng nhất giữa sản phẩm sản xuất hàng loạt và mẫu tham chiếu.": "Le produit est comparé à l'échantillon approuvé par l'acheteur pour garantir la cohérence entre le produit fabriqué en série et l'échantillon de référence.",
    "Sản phẩm được tháo rời để tối ưu vận chuyển và lưu kho.": "Le produit est démonté pour un transport et un stockage optimaux.",
