    "Bao gồm: Hình sản phẩm, Hình lỗi nếu có, Hình đóng gói, Hình container, Hình kiểm tra thực tế.": "Incluye: Imagen del producto, Imagen de error, si corresponde, Imagen del empaque, Imagen del contenedor, Imagen de inspección real.",
    "Bao gồm: Kích thước, Kết cấu, Hoàn thiện, Chức năng, Đóng gói, Số lượng.": "Incluyendo: Tamaño, Estructura, Acabado, Función, Embalaje, Cantidad.",
    "Bao gồm: Mô tả sai lệch, Mức độ ảnh hưởng, Đề xuất xử lý, Tình trạng khắc phục.": "Incluyendo: descripción de la desviación, nivel de impacto, tratamiento sugerido, estado de remediación.",
    "Bao gồm: Tên dự án, Buyer, Nhà máy, Mã sản phẩm, Ngày kiểm tra, Người thực hiện.": "Incluyendo: Nombre del proyecto, Comprador, Fábrica, Código de producto, Fecha de inspección, Implementador.",
    "Bảo vệ bề mặt": "Protección de superficies",
    "Bảo vệ các khu vực dễ trầy xước hoặc hư hỏng trong quá trình vận chuyển.": "Proteja las áreas que se rayan o dañan fácilmente durante el transporte.",
