    "Bề mặt": "Superficie",
    "Bề mặt gia công": "Superficie mecanizada",
    "Bề mặt hoàn thiện": "Acabado superficial",
    "Bề mặt sơn": "Superficie pintada",
    "Bề mặt vật liệu": "Superficie del material",
    "Biên bản xử lý sai lệch (nếu có)": "Acta de manejo de discrepancias (si las hubiera)",
    "Biến dạng": "Deformación",
    "Bộ phận tủ": "Partes del gabinete",
    "Bộ phụ kiện": "Conjunto de accesorios",
    "Bộ vít": "Juego de tornillos",
    "Buyer có thể gửi bản vẽ kỹ thuật, checklist QC hoặc tiêu chuẩn sản xuất để ANSLIFE đánh giá và đề xuất phương án kiểm tra phù hợp.": "Los compradores pueden enviar dibujos técnicos, listas de verificación de control de calidad o estándares de producción para que ANSLIFE evalúe y proponga planes de inspección adecuados.",
    "Buyer có thể gửi bản vẽ, tiêu chuẩn chất lượng, checklist QC hoặc yêu cầu kiểm tra để ANSLIFE đánh giá và đề xuất quy trình kiểm soát phù hợp.": "Los compradores pueden enviar dibujos, estándares de calidad, listas de verificación de control de calidad o solicitudes de inspección para que ANSLIFE evalúe y proponga procedimientos de control adecuados.",
    "Buyer có thể gửi checklist QC, tiêu chuẩn kiểm tra hoặc yêu cầu đánh giá riêng để ANSLIFE xây dựng phương án kiểm tra phù hợp trước khi giao hàng.": "El comprador puede enviar una lista de verificación de control de calidad, estándares de inspección o solicitar una evaluación por separado para que ANSLIFE pueda desarrollar un plan de inspección adecuado antes de la entrega.",
    "Buyer có thể gửi danh mục vật liệu, bản vẽ, mẫu vật liệu hoặc tiêu chuẩn kỹ thuật để ANSLIFE đánh giá và đề xuất phương án kiểm tra phù hợp.": "El comprador puede enviar una lista de materiales, dibujos, muestras de materiales o normas técnicas para que ANSLIFE evalúe y proponga planes de inspección adecuados.",
    "Buyer có thể gửi mẫu sản phẩm, mẫu vật liệu, bảng màu, bản vẽ kỹ thuật hoặc tiêu chuẩn đóng gói để ANSLIFE xây dựng phương án quản lý và kiểm soát phù hợp.": "Los compradores pueden enviar muestras de productos, muestras de materiales, paletas de colores, dibujos técnicos o estándares de embalaje a ANSLIFE para desarrollar un plan de gestión y control adecuado.",
    "Buyer có thể gửi tiêu chuẩn đóng gói, quy cách carton, yêu cầu pallet hoặc hướng dẫn vận chuyển để ANSLIFE đánh giá và đề xuất phương án phù hợp.": "El comprador puede enviar estándares de embalaje, especificaciones de cartón, requisitos de paletas o instrucciones de envío para que ANSLIFE evalúe y proponga una solución adecuada.",
    "Buyer có thể gửi tiêu chuẩn kỹ thuật, mẫu sản phẩm, checklist QC hoặc yêu cầu kiểm tra để ANSLIFE đánh giá và đề xuất phương án kiểm soát phù hợp.": "Los compradores pueden enviar normas técnicas, muestras de productos, listas de verificación de control de calidad o solicitudes de inspección para que ANSLIFE evalúe y proponga planes de control adecuados.",
    "Buyer có thể gửi yêu cầu kỹ thuật, tiêu chuẩn chất lượng hoặc điều kiện sử dụng của sản phẩm để ANSLIFE đánh giá và đề xuất phương án kiểm soát phù hợp.": "Los compradores pueden presentar requisitos técnicos, estándares de calidad o condiciones de uso del producto para que ANSLIFE evalúe y proponga planes de control adecuados.",
    "Buyer có thể gửi yêu cầu về biểu mẫu báo cáo, checklist QC hoặc tiêu chuẩn đánh giá để ANSLIFE xây dựng hệ thống báo cáo phù hợp với từng dự án.": "Los compradores pueden enviar solicitudes de formularios de informes, listas de verificación de control de calidad o estándares de evaluación para que ANSLIFE pueda crear un sistema de informes adecuado para cada proyecto.",
    "Buyer có thể theo dõi kết quả kiểm tra một cách rõ ràng.": "El comprador puede controlar claramente los resultados de la inspección.",
    "Các báo cáo kiểm tra được lưu cùng với mẫu duyệt, bản vẽ kỹ thuật, bảng màu, tiêu chuẩn đóng gói và checklist QC nhằm hỗ trợ truy xuất và duy trì tính nhất quán cho các dự án dài hạn.": "Los informes de inspección se guardan con muestras de aprobación, dibujos técnicos, tablas de colores, estándares de embalaje y listas de verificación de control de calidad para ayudar a la trazabilidad y mantener la coherencia en proyectos a largo plazo.",
    "Các bộ phận điều chỉnh": "Piezas de ajuste",
    "Các bộ phận và cấu kiện được xác nhận trước khi sản xuất hàng loạt.": "Las piezas y componentes se validan antes de la producción en masa.",
    "Các công đoạn gia công và lắp ráp được kiểm tra định kỳ.": "Periódicamente se inspeccionan las etapas de mecanizado y montaje.",
    "CÁC CÔNG ĐOẠN KIỂM TRA CHÍNH": "PRINCIPALES ETAPAS DE INSPECCIÓN",
